-- seed/002_demo_timetable.sql
-- A small published timetable for the demo tenant, so the public student
-- contract returns real data instead of null.
--
-- Idempotent: safe to run repeatedly. Assumes the demo tenant 'demo-kolledzh'
-- and the demo admin already exist.

