-- Publish the version. published_schedules is append-only, so guard on the
-- existing row rather than deleting history.
insert into public.published_schedules (tenant_id, schedule_version_id, published_by)
select '90000000-0000-0000-0000-000000000001',
       'c0000000-0000-0000-0000-000000000010',
       (select user_id from public.user_roles
         where tenant_id = '90000000-0000-0000-0000-000000000001' limit 1)
where not exists (
  select 1 from public.published_schedules
  where schedule_version_id = 'c0000000-0000-0000-0000-000000000010'
);
